def benchmark_agent_lifecycle():
    """Benchmark agent creation and destruction."""
    llm = FastMockLLM()

    def run():
        agent = Agent(
            llm=llm,
            config=AgentConfig(enable_planning=False)
        )
        agent.run("Test")
        agent.reset()

    return benchmark("Agent Lifecycle (create + run + reset)", run, iterations=500, warmup=50)
